<script setup lang="ts">
import { computed, reactive, ref, watch } from "vue";
import { useRoute } from "vue-router";
import { ElMessage } from "element-plus";
import { teacherGet, type PageResult, type TeacherClass, type TeacherStudent, type TeacherSubmission } from "../../../teacher/teacherApi";
import { languageLabel, monacoLanguage } from "../../../data/languages";
import { formatDisplayDateTime } from "../../../lib/format";
import CodeEditor from "../../components/CodeEditor.vue";

const route=useRoute();const practiceMode=computed(()=>route.path==="/teacher/practices/submissions");const rows=ref<TeacherSubmission[]>([]);const total=ref(0);const classes=ref<TeacherClass[]>([]);const classMap=ref<Record<number,string>>({});const practiceOptions=ref<string[]>([]);const languageOptions=ref<string[]>([]);const statusOptions=ref<string[]>([]);const loading=ref(false);const page=ref(1);const pageSize=ref(50);const codeDialog=ref(false);const codeLoading=ref(false);const code=ref("");const codeLang=ref("plaintext");
const filters=reactive({student:"",problem:"",keyword:"",classId:"",practice:"",language:"",status:"",from:"",to:""});
const visibleRows=computed(()=>{if(!practiceMode.value)return rows.value;return rows.value.filter(row=>row.practiceTitle&&(!filters.student||`${row.displayName??""} ${row.username??""}`.toLocaleLowerCase().includes(filters.student.toLocaleLowerCase()))&&(!filters.problem||(row.problemTitle??"").toLocaleLowerCase().includes(filters.problem.toLocaleLowerCase()))&&(!filters.language||row.language===filters.language)&&(!filters.status||row.status===filters.status)&&(!filters.classId||(classMap.value[row.userId]??"").toLocaleLowerCase().includes(filters.classId.toLocaleLowerCase()))&&(!filters.practice||row.practiceTitle===filters.practice));});
async function load(){loading.value=true;try{if(practiceMode.value){const [result,students]=await Promise.all([teacherGet<PageResult<TeacherSubmission>>("/api/teacher/v1/submissions?page=1&pageSize=1000&sortBy=submitTime&sortOrder=desc"),teacherGet<TeacherStudent[]>("/api/teacher/v1/students")]);rows.value=result.list??[];classMap.value=Object.fromEntries(students.filter(student=>student.className).map(student=>[student.userId,student.className!]));practiceOptions.value=[...new Set(rows.value.filter(row=>row.practiceTitle).map(row=>row.practiceTitle!))].sort();languageOptions.value=[...new Set(rows.value.filter(row=>row.practiceTitle).map(row=>row.language))].sort();statusOptions.value=[...new Set(rows.value.filter(row=>row.practiceTitle).map(row=>row.status))].sort();total.value=rows.value.length;}else{if(!classes.value.length)classes.value=await teacherGet<TeacherClass[]>("/api/teacher/v1/classes");const params=new URLSearchParams({page:String(page.value),pageSize:"50",sortBy:"submitTime",sortOrder:"desc"});if(filters.language)params.set("language",filters.language);if(filters.status)params.set("status",filters.status);if(filters.classId)params.set("classId",filters.classId);if(filters.from)params.set("from",`${filters.from}T00:00:00`);if(filters.to)params.set("to",`${filters.to}T23:59:59`);const result=await teacherGet<PageResult<TeacherSubmission>>(`/api/teacher/v1/submissions?${params.toString()}`);let list=result.list??[];if(filters.keyword.trim()){const query=filters.keyword.trim().toLocaleLowerCase();list=list.filter(item=>`${item.displayName??""} ${item.problemTitle??""} ${item.id}`.toLocaleLowerCase().includes(query));}rows.value=list;total.value=result.total??0;}}catch(cause){ElMessage.error(cause instanceof Error?cause.message:"提交记录加载失败");}finally{loading.value=false;}}
async function viewCode(row:TeacherSubmission){codeDialog.value=true;codeLoading.value=true;code.value="";codeLang.value=monacoLanguage(row.language);try{code.value=await teacherGet<string>(`/api/teacher/v1/submissions/${row.id}/code`);}catch(cause){code.value=cause instanceof Error?cause.message:"代码加载失败";}finally{codeLoading.value=false;}}
function reset(){Object.assign(filters,{student:"",problem:"",keyword:"",classId:"",practice:"",language:"",status:"",from:"",to:""});page.value=1;void load();}
watch(()=>route.path,()=>{page.value=1;void load();},{immediate:true});
</script>
<template><section class="submissions-page page-container">
  <el-card shadow="never"><div v-if="practiceMode" class="filters"><el-select v-model="filters.practice" clearable placeholder="题单"><el-option v-for="value in practiceOptions" :key="value" :value="value" :label="value"/></el-select><el-input v-model="filters.student" clearable placeholder="学生"/><el-input v-model="filters.problem" clearable placeholder="题目"/><el-select v-model="filters.language" clearable placeholder="语言"><el-option v-for="value in languageOptions" :key="value" :value="value" :label="languageLabel(value)"/></el-select><el-select v-model="filters.status" clearable placeholder="状态"><el-option v-for="value in statusOptions" :key="value" :value="value" :label="value"/></el-select><el-input v-model="filters.classId" clearable placeholder="班级"/></div><div v-else class="filters"><el-input v-model="filters.keyword" clearable placeholder="搜索学生、题目或提交 ID"/><el-select v-model="filters.classId" clearable placeholder="班级"><el-option v-for="room in classes" :key="room.id" :value="String(room.id)" :label="room.name"/></el-select><el-select v-model="filters.language" clearable placeholder="语言"><el-option label="C" value="c"/><el-option label="C++17" value="cpp17"/><el-option label="C++20" value="cpp20"/><el-option label="C++23" value="cpp23"/><el-option label="Python" value="python"/><el-option label="Java" value="java"/></el-select><el-select v-model="filters.status" clearable placeholder="状态"><el-option v-for="value in ['AC','WA','TLE','MLE','RE','CE']" :key="value" :value="value" :label="value"/></el-select><el-date-picker v-model="filters.from" type="date" value-format="YYYY-MM-DD" placeholder="开始日期"/><el-date-picker v-model="filters.to" type="date" value-format="YYYY-MM-DD" placeholder="结束日期"/></div><div v-if="!practiceMode" class="filter-actions"><el-button @click="reset">重置</el-button><el-button type="primary" @click="page=1;load()">搜索</el-button></div></el-card>
  <el-card shadow="never"><template #header><strong>{{practiceMode?'题单提交记录':'提交列表'}}</strong></template><el-table v-loading="loading" :data="visibleRows" stripe><el-table-column prop="id" label="提交 ID" width="95"/><el-table-column label="学生" min-width="140"><template #default="{row}">{{row.displayName||row.username||'-'}}</template></el-table-column><el-table-column v-if="practiceMode" label="班级" min-width="120"><template #default="{row}">{{classMap[row.userId]||'-'}}</template></el-table-column><el-table-column prop="problemTitle" label="题目" min-width="180"/><el-table-column v-if="practiceMode" prop="practiceTitle" label="题单" min-width="160"/><el-table-column v-else label="题单/比赛" min-width="170"><template #default="{row}">{{row.practiceTitle||row.contestTitle||'-'}}</template></el-table-column><el-table-column label="语言" width="100"><template #default="{row}">{{languageLabel(row.language)}}</template></el-table-column><el-table-column prop="status" label="状态" width="110"><template #default="{row}"><el-tag :type="row.status==='AC'||row.status==='ACCEPTED'?'success':['WA','RE'].includes(row.status)?'danger':'warning'">{{row.status}}</el-tag></template></el-table-column><el-table-column label="提交时间" min-width="170"><template #default="{row}">{{row.submitTime?formatDisplayDateTime(row.submitTime):'-'}}</template></el-table-column><el-table-column label="操作" width="110"><template #default="{row}"><el-button link type="primary" @click="viewCode(row)">查看代码</el-button></template></el-table-column></el-table><div v-if="!practiceMode" class="pagination"><Pagination v-model:page="page" :limit="50" :total="total" @pagination="load"/></div><el-empty v-if="!loading&&!visibleRows.length" description="暂无提交记录"/></el-card>
  <el-dialog class="qoj-management-dialog" v-model="codeDialog" title="提交代码" width="min(1000px,92vw)"><el-skeleton v-if="codeLoading" :rows="8" animated/><div v-else class="code-editor"><CodeEditor v-model="code" :language="codeLang" read-only/></div></el-dialog>
</section></template>
<style scoped>.submissions-page{display:flex;flex-direction:column;gap:16px}.page-heading,.filters,.filter-actions,.pagination{display:flex;align-items:center;gap:10px}.page-heading,.pagination{justify-content:space-between}.page-heading h1{margin:0;font-size:22px}.page-heading p{margin:6px 0 0;color:var(--el-text-color-secondary);font-size:13px}.filters{flex-wrap:wrap}.filters>*{width:170px}.filter-actions{justify-content:flex-end;margin-top:12px}.pagination{margin-top:14px}.code-editor{height:60vh;min-height:360px}@media(max-width:700px){.page-heading,.pagination{align-items:flex-start;flex-direction:column}}</style>
